VALUES
('open', 'Opens a pathname and may create or truncate a file.', 'open', NULL, 'open_effect', 'path, dirfd/base path, flags (including open_how), mode, return value, errno, creation evidence', 'Conditional: read-only opens are level 0; writable access alone is not modification. O_CREAT alone does not prove creation. Confirmed new file is level 1; truncation of an existing file is level 2. Otherwise keep impact unresolved.'),
('openat', 'Opens a pathname relative to a directory descriptor and may create or truncate a file.', 'open', NULL, 'open_effect', 'path, dirfd/base path, flags (including open_how), mode, return value, errno, creation evidence', 'Conditional: read-only opens are level 0; writable access alone is not modification. O_CREAT alone does not prove creation. Confirmed new file is level 1; truncation of an existing file is level 2. Otherwise keep impact unresolved.'),
('openat2', 'Opens a pathname using structured access flags and path-resolution constraints.', 'open', NULL, 'open_effect', 'path, dirfd/base path, flags (including open_how), mode, return value, errno, creation evidence', 'Conditional: read-only opens are level 0; writable access alone is not modification. O_CREAT alone does not prove creation. Confirmed new file is level 1; truncation of an existing file is level 2. Otherwise keep impact unresolved.'),
('creat', 'Opens a file for writing with creation and truncation semantics.', 'open', NULL, 'open_effect', 'path, dirfd/base path, flags (including open_how), mode, return value, errno, creation evidence', 'Conditional: read-only opens are level 0; writable access alone is not modification. O_CREAT alone does not prove creation. Confirmed new file is level 1; truncation of an existing file is level 2. Otherwise keep impact unresolved.'),
('write', 'Writes bytes to a descriptor at its current offset.', 'write', 2, 'file_write', 'fd, target identity/type, requested bytes, returned bytes, errno, explicit offset and flags when applicable', 'Level 2 applies to file targets, not pipes, sockets or devices. Positive returned bytes establish bytes written, not that contents differ; zero bytes do not establish a modification. Do not capture buffer contents.'),
('writev', 'Writes bytes from multiple buffers to a descriptor.', 'write', 2, 'file_write', 'fd, target identity/type, requested bytes, returned bytes, errno, explicit offset and flags when applicable', 'Level 2 applies to file targets, not pipes, sockets or devices. Positive returned bytes establish bytes written, not that contents differ; zero bytes do not establish a modification. Do not capture buffer contents.'),
('pwrite64', 'Writes bytes to a descriptor using an explicit offset.', 'write', 2, 'file_write', 'fd, target identity/type, requested bytes, returned bytes, errno, explicit offset and flags when applicable', 'Level 2 applies to file targets, not pipes, sockets or devices. Positive returned bytes establish bytes written, not that contents differ; zero bytes do not establish a modification. Do not capture buffer contents.'),
('pwritev', 'Writes bytes from multiple buffers using an explicit offset.', 'write', 2, 'file_write', 'fd, target identity/type, requested bytes, returned bytes, errno, explicit offset and flags when applicable', 'Level 2 applies to file targets, not pipes, sockets or devices. Positive returned bytes establish bytes written, not that contents differ; zero bytes do not establish a modification. Do not capture buffer contents.'),
('pwritev2', 'Writes bytes from multiple buffers with offset and per-operation flags.', 'write', 2, 'file_write', 'fd, target identity/type, requested bytes, returned bytes, errno, explicit offset and flags when applicable', 'Level 2 applies to file targets, not pipes, sockets or devices. Positive returned bytes establish bytes written, not that contents differ; zero bytes do not establish a modification. Do not capture buffer contents.'),
('unlink', 'Removes a non-directory filesystem entry.', 'delete', 3, 'remove_entry', 'path, dirfd/base path where applicable, flags, return value, errno', 'Level 3 describes the requested operation. Only success confirms removal of an entry; open descriptors or other hard links may retain the data.'),
('unlinkat', 'Removes a filesystem entry relative to a directory descriptor, including directories with AT_REMOVEDIR.', 'delete', 3, 'remove_entry', 'path, dirfd/base path where applicable, flags, return value, errno', 'Level 3 describes the requested operation. Only success confirms removal of an entry; open descriptors or other hard links may retain the data.'),
('rmdir', 'Removes an empty directory.', 'delete', 3, 'remove_entry', 'path, dirfd/base path where applicable, flags, return value, errno', 'Level 3 describes the requested operation. Only success confirms removal of an entry; open descriptors or other hard links may retain the data.'),
('rename', 'Moves a filesystem entry and may replace an existing destination.', 'rename', NULL, 'rename_effect', 'source and destination paths/base descriptors, flags, return value, errno, destination replacement evidence', 'Confirmed move without replacement is level 2; confirmed destination replacement is level 3. Unknown replacement stays unresolved. RENAME_EXCHANGE exchanges entries (level 2); RENAME_WHITEOUT needs explicit interpretation. Successful same-object rename may be a no-op.'),
('renameat', 'Moves a filesystem entry using directory-relative source and destination paths.', 'rename', NULL, 'rename_effect', 'source and destination paths/base descriptors, flags, return value, errno, destination replacement evidence', 'Confirmed move without replacement is level 2; confirmed destination replacement is level 3. Unknown replacement stays unresolved. RENAME_EXCHANGE exchanges entries (level 2); RENAME_WHITEOUT needs explicit interpretation. Successful same-object rename may be a no-op.'),
('renameat2', 'Moves or exchanges filesystem entries with flag-controlled replacement behavior.', 'rename', NULL, 'rename_effect', 'source and destination paths/base descriptors, flags, return value, errno, destination replacement evidence', 'Confirmed move without replacement is level 2; confirmed destination replacement is level 3. Unknown replacement stays unresolved. RENAME_EXCHANGE exchanges entries (level 2); RENAME_WHITEOUT needs explicit interpretation. Successful same-object rename may be a no-op.'),
('truncate', 'Sets the length of a file identified by pathname.', 'resize', 2, 'file_resize', 'path or fd target identity/type, requested length, return value, errno, prior length when known', 'Success confirms the length-setting operation, not necessarily a length change; compare prior size only when reliable.'),
('ftruncate', 'Sets the length of a file identified by descriptor.', 'resize', 2, 'file_resize', 'path or fd target identity/type, requested length, return value, errno, prior length when known', 'Success confirms the length-setting operation, not necessarily a length change; compare prior size only when reliable.'),
('mkdir', 'Creates a directory with the requested permissions subject to the process umask.', 'create_directory', 1, 'directory_create', 'path, dirfd/base path where applicable, mode, return value, errno', 'Only success confirms directory creation. Record requested mode, not an assumed effective mode.'),
('mkdirat', 'Creates a directory relative to a directory descriptor.', 'create_directory', 1, 'directory_create', 'path, dirfd/base path where applicable, mode, return value, errno', 'Only success confirms directory creation. Record requested mode, not an assumed effective mode.'),
('read', 'Reads bytes from a descriptor.', 'read', 0, 'file_read', 'fd, target identity/type, requested bytes, returned bytes, errno, explicit offset and flags when applicable', 'Level 0 describes observation, not safety; secret reads can be sensitive and reads can update atime. Zero returned bytes do not prove content was read. Exclude non-file targets from filesystem classification.'),
('readv', 'Reads bytes from a descriptor into multiple buffers.', 'read', 0, 'file_read', 'fd, target identity/type, requested bytes, returned bytes, errno, explicit offset and flags when applicable', 'Level 0 describes observation, not safety; secret reads can be sensitive and reads can update atime. Zero returned bytes do not prove content was read. Exclude non-file targets from filesystem classification.'),
