    default_impact_level=excluded.default_impact_level,
    classification_rule=excluded.classification_rule,
    required_evidence=excluded.required_evidence,
    interpretation_notes=excluded.interpretation_notes,
    catalog_version=excluded.catalog_version;

CREATE VIEW IF NOT EXISTS syscall_catalog_readable AS
SELECT s.syscall_name, s.description, s.category_id, c.label AS category,
       s.default_impact_level, i.label AS impact_label,
       s.classification_rule, s.required_evidence, s.interpretation_notes,
       s.catalog_version
FROM syscall_catalog AS s
JOIN syscall_categories AS c ON c.category_id = s.category_id
LEFT JOIN syscall_impact_levels AS i ON i.level = s.default_impact_level;

COMMIT;

-- Example: SELECT syscall_name, category, default_impact_level
--          FROM syscall_catalog_readable WHERE syscall_name = 'unlinkat';
-- Result: unlinkat | Delete | 3

